// Synthetic SGC markup. Never replace these fixtures with live customer HTML.
const page = content => `<!doctype html><html><head><title>SGC</title></head><body><a href="https://sgc.yadinero.co/logout">Salir</a>${content}</body></html>`;
const listRow = (doc = '12345678', name = 'Cliente de prueba', id = '101') => `<tr><td>CC- ${doc} <span class="badge badge-danger">Bloqueo Fianza</span></td><td><h5>${name}</h5><small>Dato fuera del resumen</small></td><td><i class="icon wb-check"></i></td><td>RECHAZADO</td><td>Turquesa</td><td>D</td><td>0000</td><td><a href="/customers/edit/${id}">Editar</a><a href="/customers/show/${id}">Ver</a></td></tr>`;
const list = (row = listRow()) => page(`<table><thead><tr><th># Identificacion</th><th>Nombre completo</th><th>Estado</th><th>Estado última solicitud</th><th>Categoría</th><th>Perfil</th><th>Código de referido</th><th>Acciones</th></tr></thead><tbody>${row}</tbody></table>`);
const requestRow = (id, created = 'Oct 14, 2026') => `<tr><td><a href="https://sgc.yadinero.co/requests/edit/${id}">${id}</a></td><td>120,000</td><td>RECHAZADO</td><td>30</td><td>${created}</td><td>D</td><td>Dato reservado</td><td>Rechazo por intentos de firma Auco</td><td><a href="/requests/show/${id}">Ver</a></td></tr>`;
const detail = (requestRows = requestRow('200'), creditRows = '') => page(`<h1>Información del cliente</h1><p># Identificación: CC-12345678 Teléfono: PRIVATE_CONTACT_SENTINEL</p><table><thead><tr><th>ID</th><th>Valor solicitado</th><th>Estado</th><th># Días</th><th>Creado</th><th>Perfil</th><th>Score Cifin</th><th>Tipificación</th><th>Acciones</th></tr></thead><tbody>${requestRows || '<tr><td colspan="9">Sin solicitudes</td></tr>'}</tbody></table><table><thead><tr><th>ID</th><th>Valor Facturado</th><th>Saldo</th><th>Creado</th><th>Acciones</th></tr></thead><tbody>${creditRows || '<tr><td colspan="5">Cliente sin créditos</td></tr>'}</tbody></table>`);
const counter = (label, value) => `<div class="counter counter-xs"><div class="counter-label text">${label}</div><div class="counter-number-group"><i class="icon"></i>${value}</div></div>`;
const request = (owner = '101', doc = '12345678') => page(`<h1>Solicitud - Crédito rotativo - 200</h1><a href="/customers/show/${owner}">Cliente de prueba</a><input name="doc_num" value="${doc}">${counter('Estado de la solicitud', 'RECHAZADO')}${counter('Tipificación', 'Rechazo por intentos de firma Auco')}${counter('Valor Crédito', 'COP 120,000')}${counter('Valor a pagar', 'COP 185,074')}${counter('Creado', '2026-10-14 15:37:17')}${counter('Fecha Límite', 'Nov 13, 2026')}${counter('Días del Crédito', '30')}<input name="_token" value="SECRET_SENTINEL"><div id="coments_div"><div class="panel-body"><ul>${Array.from({ length: 8 }, (_, i) => `<li class="list-group-item"><small class="badge">Cambio de estado</small><p>${i ? 'Cambio de estado a: RECHAZADO' : 'Auco respuesta: IDENTITY_GUARD_BLOCKED'}</p><small>Realizado por PRIVATE_ACTOR_SENTINEL <time>2026-10-15 11:27:12</time><br></small><small>Desde IP <span>PRIVATE_IP_SENTINEL</span></small></li>`).join('')}</ul></div></div><script>throw new Error('must never execute')</script>`);
module.exports = { page, listRow, list, requestRow, detail, request };
